package org.apache.commons.math3.distribution;

import org.apache.commons.math3.exception.DimensionMismatchException;
import org.junit.Test;
import static org.junit.Assert.assertEquals;

public class AgentBRT_Math_11_raw_diff_Test {

    @Test
    public void testReproduceBug() {
        double[] means = {0.0, 0.0};
        double[][] covariances = {
            {1.0, 0.0},
            {0.0, 1.0}
        };
        MultivariateNormalDistribution distribution = new MultivariateNormalDistribution(means, covariances);

        double[] point = {0.0, 0.0};
        double expectedDensity = 1 / (2 * Math.PI); // Correct density for 2D standard normal at mean
        double actualDensity = distribution.density(point);

        assertEquals("Density calculation is incorrect", expectedDensity, actualDensity, 1e-9);
    }
}

